def encode(s):
    """Run-length encode s, omitting the count when it is 1."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1

        count = j - i
        result.append(ch)
        if count > 1:
            result.append(str(count))
        i = j

    return ''.join(result)


def decode(s):
    """Decode a run-length encoded string."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]
        i += 1

        j = i
        while j < n and s[j].isdigit():
            j += 1

        if j > i:
            count = int(s[i:j])
            i = j
        else:
            count = 1

        result.append(ch * count)

    return ''.join(result)
